import { IClubCreateOrUpdateDTO } from '../@types/clubs.dto.types';
import { IClub } from '../@types/clubs.types';

export const mapClubToBack = (data: IClub): IClubCreateOrUpdateDTO => {
  return {
    id: data.id,
    code: data.code,
    name: data.name,
    full_name: data.full_name,
    logo: data.logo,
    logo_full: data.logo_full,
    id_parent: data.parent ? data.parent.id : null,
    foundation_at: data.foundation_at,
    description: data.description,
    link: data.link,
    comment: data.comment,
    is_public: data.is_public ? '1' : '0',
    id_geo_region: data.geoRegion.id,
  };
};
